// 固定名稱／序號別名是解析與匯出列舉的共用來源，不探測空序號。
struct ServiceExportAlias { std::string_view family, symbol, target_family, target_symbol; };
// Windows 以 forwarder 匯出的整組模組關係：前者與後者同名的匯出（DllXxx 自我註冊入口除外）轉發到後者，
// GetProcAddress 與匯入繫結兩邊取得同一位址。一般的跨模組別名只是共用實作，不在此列。
struct BuiltinModuleForwarder { std::string_view module, target; };
inline constexpr BuiltinModuleForwarder builtin_module_forwarders[]{{"ole32.dll","combase.dll"}};
inline std::string_view builtin_module_forwarder(std::string_view module){
    for(const auto& item:builtin_module_forwarders)if(item.module==module)return item.target;
    return {};
}
